          const buttons = [...popup.querySelectorAll(".reaction__emoji-btn")]
          const hidden = buttons.filter(btn => {
            const r = btn.getBoundingClientRect()
            const hit = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2)
            return !(hit === btn || btn.contains(hit))
          }).length
          return { rect: [Math.round(b.left), Math.round(b.right), Math.round(b.top), Math.round(b.bottom)], viewport: window.innerWidth, buttons: buttons.length, notHittable: hidden }
