cd /app && cat > /tmp/systest/stack.rb <<'EOF'

  test "stacking debug" do
    card = cards(:logo)
    sign_in_as(users(:david))
    [ [ 1200, 1000 ], [ 390, 844 ] ].each do |width, height|
      page.current_window.resize_to(width, height)
      visit card_url(card)
      frame = "##{dom_id(card, :reacting)}"
      within(frame) { find(".reactions__trigger").click; find(".reaction__menu-btn").click }
      sleep 0.3
      result = page.evaluate_script(<<~JS)
        (() => {
          const out = []
          let el = document.querySelector("#{frame} .reaction__popup")
          while (el && el !== document.body) {
            const cs = getComputedStyle(el)
            out.push([el.tagName.toLowerCase() + (el.className && typeof el.className === "string" ? "." + el.className.trim().split(/\\s+/).slice(0,2).join(".") : ""), cs.display, cs.position, cs.zIndex, cs.transform !== "none" ? "T" : "", cs.contain].join(" "))
            el = el.parentElement
          }
          const popup = document.querySelector("#{frame} .reaction__popup")
          const btn = [...popup.querySelectorAll(".reaction__emoji-btn")].find(btn => { const r = btn.getBoundingClientRect(); const hit = document.elementFromPoint(r.left + r.width/2, r.top + r.height/2); return !(hit === btn || btn.contains(hit)) })
          let coverChain = []
          if (btn) {
            const r = btn.getBoundingClientRect()
            let hit = document.elementFromPoint(r.left + r.width/2, r.top + r.height/2)
            while (hit && hit !== document.body) { const cs = getComputedStyle(hit); coverChain.push([hit.tagName.toLowerCase() + "." + (typeof hit.className === "string" ? hit.className.trim().split(/\\s+/).slice(0,2).join(".") : ""), cs.position, cs.zIndex, cs.display].join(" ")); hit = hit.parentElement }
          }
          return { chain: out, cover: coverChain.slice(0, 8) }
        })()
      JS
      puts "== #{width}"; puts "popup ancestors:"; puts result["chain"].map { "  #{_1}" }; puts "covering element chain:"; puts result["cover"].map { "  #{_1}" }
    end
  end
end
EOF
